	protected List<Role> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Roles:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Role : " );        
		List<Role> collection  = new ArrayList<>();

		try {
			// call the static get method on the RoleService
			collection = RoleService.getRoleInstance().getAllRole();
			assertNotNull( collection, "An Empty collection of Role was incorrectly returned.");
			
			// Now print out the values
			Role entity = null;            
			Iterator<Role> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getRoleId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

